#!/usr/bin/env bash
set -euo pipefail
PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)";BUILD_ROOT="$PROJECT_ROOT/build/sm64-modern-unused-particle-spawn";mkdir -p "$BUILD_ROOT/module-cache"
xcrun swiftc -parse-as-library -swift-version 6 -Xfrontend -strict-concurrency=complete -module-cache-path "$BUILD_ROOT/module-cache" "$PROJECT_ROOT/SM64Modern/UnusedParticleSpawnBehavior.swift" "$PROJECT_ROOT/tests/sm64_modern_unused_particle_spawn_smoke.swift" -o "$BUILD_ROOT/smoke";sout="$($BUILD_ROOT/smoke)";printf '%s\n' "$sout";xcrun clang -std=c11 "$PROJECT_ROOT/tests/sm64_modern_unused_particle_spawn_contract.c" -o "$BUILD_ROOT/contract";cout="$($BUILD_ROOT/contract)";printf '%s\n' "$cout";s="$(printf '%s\n' "$sout"|sed -n 's/^unusedParticleSpawnFingerprint=//p')";c="$(printf '%s\n' "$cout"|sed -n 's/^unusedParticleSpawnFingerprint=//p')";[[ -n "$s"&&"$s" == "$c" ]]||{ echo "unused particle mismatch Swift=$s C=$c" >&2;exit 1;};printf '%s\n' 'Swift/C unused particle spawn contract matched'
